CREATE TABLE "focus_rooms" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "owner_user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE cascade, "workspace_id" uuid, "title" varchar(160) NOT NULL, "description" text, "visibility" varchar(20) DEFAULT 'public' NOT NULL, "mode" varchar(20) DEFAULT 'casual' NOT NULL, "goal_type" varchar(30), "goal_target" integer, "max_members" integer, "expires_at" timestamp, "task_title_visibility_default" boolean DEFAULT false NOT NULL, "statistics_visible" boolean DEFAULT true NOT NULL, "leaderboard_enabled" boolean DEFAULT false NOT NULL, "created_at" timestamp DEFAULT now() NOT NULL, "updated_at" timestamp DEFAULT now() NOT NULL);
CREATE INDEX "idx_focus_rooms_discovery" ON "focus_rooms" ("visibility","mode","expires_at"); CREATE INDEX "idx_focus_rooms_owner" ON "focus_rooms" ("owner_user_id");
CREATE TABLE "focus_room_members" ("room_id" uuid NOT NULL REFERENCES "focus_rooms"("id") ON DELETE cascade, "user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE cascade, "role" varchar(20) DEFAULT 'member' NOT NULL, "state" varchar(20) DEFAULT 'preparing' NOT NULL, "joined_at" timestamp DEFAULT now() NOT NULL, "left_at" timestamp, "anonymous" boolean DEFAULT false NOT NULL, "show_task_title" boolean DEFAULT false NOT NULL, "show_timer" boolean DEFAULT true NOT NULL, "show_statistics" boolean DEFAULT true NOT NULL, PRIMARY KEY("room_id","user_id"));
CREATE INDEX "idx_focus_room_members_user" ON "focus_room_members" ("user_id"); CREATE INDEX "idx_focus_room_members_active" ON "focus_room_members" ("room_id","left_at");
CREATE TABLE "focus_room_commitment_sessions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "room_id" uuid NOT NULL REFERENCES "focus_rooms"("id") ON DELETE cascade, "created_by" uuid NOT NULL REFERENCES "users"("id") ON DELETE restrict, "duration_minutes" integer NOT NULL, "break_minutes" integer, "started_at" timestamp, "expected_end_at" timestamp, "ended_at" timestamp, "ended_by_user_id" uuid REFERENCES "users"("id") ON DELETE set null, "end_reason" varchar(50), "collective_end_policy" varchar(40) DEFAULT 'any_participant' NOT NULL, "reconnect_grace_seconds" integer DEFAULT 60 NOT NULL, "termination_version" integer DEFAULT 0 NOT NULL, "termination_command_id" uuid, "reconciliation_status" varchar(20) DEFAULT 'not_required' NOT NULL, "status" varchar(20) DEFAULT 'lobby' NOT NULL, "created_at" timestamp DEFAULT now() NOT NULL, "updated_at" timestamp DEFAULT now() NOT NULL);
CREATE INDEX "idx_focus_commitment_active" ON "focus_room_commitment_sessions" ("room_id","status"); CREATE UNIQUE INDEX "uq_focus_commitment_command" ON "focus_room_commitment_sessions" ("termination_command_id") WHERE "termination_command_id" IS NOT NULL;
CREATE TABLE "focus_room_commitment_participants" ("session_id" uuid NOT NULL REFERENCES "focus_room_commitment_sessions"("id") ON DELETE cascade, "user_id" uuid NOT NULL REFERENCES "users"("id") ON DELETE cascade, "accepted_agreement_at" timestamp, "ready_at" timestamp, "outcome" varchar(40), "left_at" timestamp, "focused_duration_minutes" integer DEFAULT 0 NOT NULL, "reconnect_deadline_at" timestamp, "recovered_disconnect" boolean DEFAULT false NOT NULL, "updated_at" timestamp DEFAULT now() NOT NULL, PRIMARY KEY("session_id","user_id"));
CREATE INDEX "idx_focus_commitment_participant_user" ON "focus_room_commitment_participants" ("user_id");
CREATE TABLE "focus_room_activity_events" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "room_id" uuid NOT NULL REFERENCES "focus_rooms"("id") ON DELETE cascade, "user_id" uuid REFERENCES "users"("id") ON DELETE set null, "event_type" varchar(50) NOT NULL, "metadata" jsonb DEFAULT '{}'::jsonb NOT NULL, "created_at" timestamp DEFAULT now() NOT NULL); CREATE INDEX "idx_focus_room_events_page" ON "focus_room_activity_events" ("room_id","created_at");
CREATE TABLE "focus_room_invitations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "room_id" uuid NOT NULL REFERENCES "focus_rooms"("id") ON DELETE cascade, "invited_user_id" uuid REFERENCES "users"("id") ON DELETE cascade, "invite_code" varchar(80), "expires_at" timestamp NOT NULL, "accepted_at" timestamp, "created_at" timestamp DEFAULT now() NOT NULL); CREATE UNIQUE INDEX "uq_focus_room_invite_code" ON "focus_room_invitations" ("invite_code") WHERE "invite_code" IS NOT NULL; CREATE INDEX "idx_focus_room_invited_user" ON "focus_room_invitations" ("invited_user_id");
ALTER TABLE "focus_sessions" ADD COLUMN "commitment_session_id" uuid REFERENCES "focus_room_commitment_sessions"("id") ON DELETE set null; ALTER TABLE "focus_sessions" ADD COLUMN "completion_reason" varchar(40); CREATE INDEX "idx_focus_sessions_commitment" ON "focus_sessions" ("commitment_session_id");
